INSERT INTO player_test_cases (module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('Logs', 'LOGS-001', 'Pregled stranice View Logs', 'Pozitivni', 'High', 'Igrač je prijavljen na staging-2.', '["Otvori My Account → View Logs.", "Pregledaj filtere i tabelu."]', '', 'Filteri: brzi filteri datuma, Date from/to, Reset, Apply.
